window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d77cf47aeb8053a6"]={"versions": [{"id": "FIG-d77cf47aeb8053a6", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Ablaufs zur Löschung diagnostischer Ereignisse und Rücknahme von Warnindikatoren innerhalb des AUTOSAR Classic Diagnostic Event Managers (Dem).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit Trigger <code>[event qualified as PASSED]</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>Check WarningIndicator Request bit = 1</code></li>\n<li><code>Check Warning-IndicatorOffCondition</code></li>\n<li><code>Event memory entry exists</code></li>\n<li><code>Aging completed</code></li>\n<li>Zusammenführungsknoten (Merge Node) vor der Prüfung des Ereignisspeichereintrags</li>\n<li>Aktionen:</li>\n<li><code>Process healing</code></li>\n<li><code>WarningIndicator Request bit = 0</code></li>\n<li><code>Process aging</code></li>\n<li><code>Delete event memory entry</code></li>\n<li><code>ConfirmedDTC bit = 0</code></li>\n<li>Endknoten (Aktivitätsendknoten)</li>\n<li>Schnittstellen/Statusflags: WarningIndicator-Request-Bit, UDS-Statusbit ConfirmedDTC (Bit 3), Event-Memory-Eintrag, Aging-Zustand</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf startet, sobald ein Ereignis als bestanden gewertet wird (<code>[event qualified as PASSED]</code>).</li>\n<li>Prüfung von <code>Check WarningIndicator Request bit = 1</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist das Bit gesetzt (<code>[TRUE]</code>), wird die Aktion <code>Process healing</code> ausgeführt.</li>\n<li>Ist das Bit nicht gesetzt (<code>[FALSE]</code>), wird der Heilungspfad übersprungen und vor die Prüfung des Ereignisspeichers verzweigt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach <code>Process healing</code> wird <code>Check Warning-IndicatorOffCondition</code> geprüft:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei Erfüllung (<code>[TRUE]</code>) wird die Aktion <code>WarningIndicator Request bit = 0</code> ausgeführt.</li>\n<li>Ist die Bedingung nicht erfüllt (<code>[FALSE]</code>), führt der Pfad direkt zum Aktivitätsendknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach dem Zurücksetzen des Warnindikators oder bei anfänglich nicht gesetztem Request-Bit folgt die Prüfung <code>Event memory entry exists</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Existiert ein Eintrag (<code>[TRUE]</code>), wird <code>Process aging</code> durchlaufen.</li>\n<li>Existiert kein Eintrag (<code>[FALSE]</code>), endet der Ablauf am Aktivitätsendknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach <code>Process aging</code> prüft <code>Aging completed</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Alterung abgeschlossen (<code>[TRUE]</code>), wird nacheinander <code>Delete event memory entry</code> und <code>ConfirmedDTC bit = 0</code> ausgeführt, bevor der Ablauf am Endknoten endet.</li>\n<li>Ist die Alterung nicht abgeschlossen (<code>[FALSE]</code>), endet der Ablauf direkt am Aktivitätsendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativer Ablauf für die Deaktivierung von Warnindikatoren (Healing) und das Löschen von Fehlerspeichereinträgen inklusive Rücksetzen des ConfirmedDTC-Bits (Aging) im Dem. Entwickler müssen beachten, dass das Aging erst nach erfolgreicher Deaktivierung des Warnindikators bzw. bei inaktivem Warnindikator durchlaufen wird und dass ohne bestehenden Ereignisspeichereintrag keine Alterung stattfindet.</p>"}, {"id": "FIG-a516e16965123a8f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing [SWS_Dem_00533]</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status- und Steuerungsflags: PDTC (PendingDTC), CDTC (ConfirmedDTC), OCY (Operation Cycle), TFTOC (TestFailedThisOperationCycle), TNCTOC (TestNotCompletedThisOperationCycle), HealingCounter, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung, dass bei <code>PDTC == 1</code> und Abschluss des Betriebszyklus mit <code>TFTOC==0 &amp;&amp; TNCTOC==0</code> das PendingDTC-Bit zurückgesetzt wird (<code>PDTC 1-&gt;0</code>).</li>\n<li>Prüfung <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> erfolgt der Übergang zu <code>Process healing [SWS_Dem_00533]</code>. Solange <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> eintritt, wird <code>HealingCounter--</code> dekrementiert (Selbstschleife). Tritt ein Fehler auf (<code>[TFTOC==1]</code>), bricht der Ablauf sofort zum Endknoten ab. Sobald <code>[HealingCounter==0]</code> erreicht ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Bei <code>[FALSE]</code> wird der Heilungsprozess umgangen und direkt zum nachfolgenden Merge-Knoten verzweigt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom Merge-Knoten führt der Pfad zur Verzweigung <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt hierbei <code>[TFTOC==1]</code> auf, endet der Ablauf direkt am Endknoten.</li>\n<li>Ist kein Eintrag vorhanden (<code>[FALSE]</code>), wird über die Aktion <code>try to allocate an event memory entry</code> versucht, einen Eintrag zu belegen, und der Pfad kehrt vor die Existenzprüfung zurück.</li>\n<li>Ist der Eintrag vorhanden (<code>[TRUE]</code>), wird <code>Process aging</code> angestoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Während <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreiem Zyklusabschluss (<code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code>) wird der Alterungszähler weitergezählt (<code>count further AgingCounter</code>).</li>\n<li>Tritt <code>[TFTOC==1]</code> auf, wird die Alterung abgebrochen und zum Endknoten verzweigt.</li>\n<li>Erreicht der Zähler den Schwellwert (<code>[DemAgingCycleCounterThreshold reached]</code>), wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und der Ablauf am Endknoten beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Zyklenüberwachung für Healing und Aging im Dem. Die Kriterien für OCY-Abschluss, TFTOC und TNCTOC müssen für jeden Zählerschritt ausgewertet werden. Ein erneutes Auftreten des Fehlers (<code>TFTOC==1</code>) bricht Healing bzw. Aging unmittelbar ab. Die Allokation eines Ereignisspeichereintrags bei Nichtexistenz unterliegt den referenzierten Einschränkungen aus SWS_Dem_00823 und SWS_Dem_00019. Die Löschung des Eintrags bedingt zwingend das Rücksetzen des ConfirmedDTC (CDTC=0).</p>"}, {"id": "FIG-5e55ddc4615bd15f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status- und Steuerungsflags: PDTC (PendingDTC), CDTC (ConfirmedDTC), OCY (Operation Cycle), TFTOC (TestFailedThisOperationCycle), TNCTOC (TestNotCompletedThisOperationCycle), HealingCounter, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung, dass bei <code>PDTC == 1</code> und Abschluss des Betriebszyklus mit <code>TFTOC==0 &amp;&amp; TNCTOC==0</code> das PendingDTC-Bit zurückgesetzt wird (<code>PDTC 1-&gt;0</code>).</li>\n<li>Prüfung <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> erfolgt der Übergang zu <code>Process healing [SWS_Dem_00533]</code>. Solange <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> eintritt, wird <code>HealingCounter--</code> dekrementiert (Selbstschleife). Tritt ein Fehler auf (<code>[TFTOC==1]</code>), bricht der Ablauf sofort zum Endknoten ab. Sobald <code>[HealingCounter==0]</code> erreicht ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Bei <code>[FALSE]</code> wird der Heilungsprozess umgangen und direkt zum nachfolgenden Merge-Knoten verzweigt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom Merge-Knoten führt der Pfad zur Verzweigung <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt hierbei <code>[TFTOC==1]</code> auf, endet der Ablauf direkt am Endknoten.</li>\n<li>Ist kein Eintrag vorhanden (<code>[FALSE]</code>), wird über die Aktion <code>try to allocate an event memory entry</code> versucht, einen Eintrag zu belegen, und der Pfad kehrt vor die Existenzprüfung zurück.</li>\n<li>Ist der Eintrag vorhanden (<code>[TRUE]</code>), wird <code>Process aging</code> angestoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Während <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreiem Zyklusabschluss (<code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code>) wird der Alterungszähler weitergezählt (<code>count further AgingCounter</code>).</li>\n<li>Tritt <code>[TFTOC==1]</code> auf, wird die Alterung abgebrochen und zum Endknoten verzweigt.</li>\n<li>Erreicht der Zähler den Schwellwert (<code>[DemAgingCycleCounterThreshold reached]</code>), wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und der Ablauf am Endknoten beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Zyklenüberwachung für Healing und Aging im Dem. Die Kriterien für OCY-Abschluss, TFTOC und TNCTOC müssen für jeden Zählerschritt ausgewertet werden. Ein erneutes Auftreten des Fehlers (<code>TFTOC==1</code>) bricht Healing bzw. Aging unmittelbar ab. Die Allokation eines Ereignisspeichereintrags bei Nichtexistenz unterliegt den referenzierten Einschränkungen aus SWS_Dem_00823 und SWS_Dem_00019. Die Löschung des Eintrags bedingt zwingend das Rücksetzen des ConfirmedDTC (CDTC=0).</p>"}, {"id": "FIG-f30cc05dfda84a1b", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status- und Steuerungsflags: PDTC (PendingDTC), CDTC (ConfirmedDTC), OCY (Operation Cycle), TFTOC (TestFailedThisOperationCycle), TNCTOC (TestNotCompletedThisOperationCycle), HealingCounter, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung, dass bei <code>PDTC == 1</code> und Abschluss des Betriebszyklus mit <code>TFTOC==0 &amp;&amp; TNCTOC==0</code> das PendingDTC-Bit zurückgesetzt wird (<code>PDTC 1-&gt;0</code>).</li>\n<li>Prüfung <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> erfolgt der Übergang zu <code>Process healing [SWS_Dem_00533]</code>. Solange <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> eintritt, wird <code>HealingCounter--</code> dekrementiert (Selbstschleife). Tritt ein Fehler auf (<code>[TFTOC==1]</code>), bricht der Ablauf sofort zum Endknoten ab. Sobald <code>[HealingCounter==0]</code> erreicht ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Bei <code>[FALSE]</code> wird der Heilungsprozess umgangen und direkt zum nachfolgenden Merge-Knoten verzweigt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom Merge-Knoten führt der Pfad zur Verzweigung <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt hierbei <code>[TFTOC==1]</code> auf, endet der Ablauf direkt am Endknoten.</li>\n<li>Ist kein Eintrag vorhanden (<code>[FALSE]</code>), wird über die Aktion <code>try to allocate an event memory entry</code> versucht, einen Eintrag zu belegen, und der Pfad kehrt vor die Existenzprüfung zurück.</li>\n<li>Ist der Eintrag vorhanden (<code>[TRUE]</code>), wird <code>Process aging</code> angestoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Während <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreiem Zyklusabschluss (<code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code>) wird der Alterungszähler weitergezählt (<code>count further AgingCounter</code>).</li>\n<li>Tritt <code>[TFTOC==1]</code> auf, wird die Alterung abgebrochen und zum Endknoten verzweigt.</li>\n<li>Erreicht der Zähler den Schwellwert (<code>[DemAgingCycleCounterThreshold reached]</code>), wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und der Ablauf am Endknoten beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Zyklenüberwachung für Healing und Aging im Dem. Die Kriterien für OCY-Abschluss, TFTOC und TNCTOC müssen für jeden Zählerschritt ausgewertet werden. Ein erneutes Auftreten des Fehlers (<code>TFTOC==1</code>) bricht Healing bzw. Aging unmittelbar ab. Die Allokation eines Ereignisspeichereintrags bei Nichtexistenz unterliegt den referenzierten Einschränkungen aus SWS_Dem_00823 und SWS_Dem_00019. Die Löschung des Eintrags bedingt zwingend das Rücksetzen des ConfirmedDTC (CDTC=0).</p>"}, {"id": "FIG-8c9f388e0795110b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status- und Steuerungsflags: PDTC (PendingDTC), CDTC (ConfirmedDTC), OCY (Operation Cycle), TFTOC (TestFailedThisOperationCycle), TNCTOC (TestNotCompletedThisOperationCycle), HealingCounter, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung, dass bei <code>PDTC == 1</code> und Abschluss des Betriebszyklus mit <code>TFTOC==0 &amp;&amp; TNCTOC==0</code> das PendingDTC-Bit zurückgesetzt wird (<code>PDTC 1-&gt;0</code>).</li>\n<li>Prüfung <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TRUE]</code> erfolgt der Übergang zu <code>Process healing [SWS_Dem_00533]</code>. Solange <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> eintritt, wird <code>HealingCounter--</code> dekrementiert (Selbstschleife). Tritt ein Fehler auf (<code>[TFTOC==1]</code>), bricht der Ablauf sofort zum Endknoten ab. Sobald <code>[HealingCounter==0]</code> erreicht ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Bei <code>[FALSE]</code> wird der Heilungsprozess umgangen und direkt zum nachfolgenden Merge-Knoten verzweigt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Vom Merge-Knoten führt der Pfad zur Verzweigung <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt hierbei <code>[TFTOC==1]</code> auf, endet der Ablauf direkt am Endknoten.</li>\n<li>Ist kein Eintrag vorhanden (<code>[FALSE]</code>), wird über die Aktion <code>try to allocate an event memory entry</code> versucht, einen Eintrag zu belegen, und der Pfad kehrt vor die Existenzprüfung zurück.</li>\n<li>Ist der Eintrag vorhanden (<code>[TRUE]</code>), wird <code>Process aging</code> angestoßen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Während <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei fehlerfreiem Zyklusabschluss (<code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code>) wird der Alterungszähler weitergezählt (<code>count further AgingCounter</code>).</li>\n<li>Tritt <code>[TFTOC==1]</code> auf, wird die Alterung abgebrochen und zum Endknoten verzweigt.</li>\n<li>Erreicht der Zähler den Schwellwert (<code>[DemAgingCycleCounterThreshold reached]</code>), wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und der Ablauf am Endknoten beendet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Spezifikation der Zyklenüberwachung für Healing und Aging im Dem. Die Kriterien für OCY-Abschluss, TFTOC und TNCTOC müssen für jeden Zählerschritt ausgewertet werden. Ein erneutes Auftreten des Fehlers (<code>TFTOC==1</code>) bricht Healing bzw. Aging unmittelbar ab. Die Allokation eines Ereignisspeichereintrags bei Nichtexistenz unterliegt den referenzierten Einschränkungen aus SWS_Dem_00823 und SWS_Dem_00019. Die Löschung des Eintrags bedingt zwingend das Rücksetzen des ConfirmedDTC (CDTC=0).</p>"}, {"id": "FIG-174cf92ad4795b42", "releases": ["R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status-, Zähler- und Schwellwertparameter: PDTC, CDTC, OCY, TFTOC, TNCTOC, HealingCounter, DemIndicatorHealingCycleCounterThreshold, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung <code>PDTC == 1</code> mit Statusübergang <code>PDTC 1-&gt;0</code> bei <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code>.</li>\n<li>Entscheidungsknoten <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Prüfung <code>[TRUE]</code>, geht der Kontrollfluss zu <code>Process healing</code>. Bei <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> wird der Heilungszähler inkrementiert (<code>count further HealingCounter</code>). Tritt <code>[TFTOC==1]</code> ein, wird zum Endknoten verzweigt. Sobald <code>[DemIndicatorHealingCycleCounterThreshold reached]</code> erfüllt ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Ergibt die Prüfung <code>[FALSE]</code>, führt der Pfad am Heilungszweig vorbei zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach dem Merge-Knoten folgt <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TFTOC==1]</code> bricht der Ablauf zum Endknoten ab.</li>\n<li>Ergibt die Auswertung <code>[FALSE]</code>, wird <code>try to allocate an event memory entry</code> aufgerufen und zum Merge-Knoten zurückgeführt.</li>\n<li>Ergibt die Prüfung <code>[TRUE]</code>, wird <code>Process aging</code> erreicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>In <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code> wird <code>count further AgingCounter</code> ausgeführt.</li>\n<li>Bei <code>[TFTOC==1]</code> erfolgt der Abbruch zum Endknoten.</li>\n<li>Bei <code>[DemAgingCycleCounterThreshold reached]</code> wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und die Aktivität endet am Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Zählerlogik für den Heilungsprozess: Die Heilschwelle wird nun über das Erreichen des Schwellwerts <code>DemIndicatorHealingCycleCounterThreshold</code> mittels Hochzählens (<code>count further HealingCounter</code>) gesteuert, analog zur Funktionsweise des Aging-Zählers (<code>DemAgingCycleCounterThreshold</code>). Entwickler müssen sicherstellen, dass die Konfigurationsparameter für beide Zyklusschwellen konsistent parametriert sind.</p>"}, {"id": "FIG-4b1967973b70d0a1", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des sequenziellen Verhaltens bei Heilung (Healing), Ereignisspeicherallokation und Alterung (Aging) zur Löschung von Diagnoseereignissen im Dem (AUTOSAR Classic Platform).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten mit annotierter PreCondition-Notiz: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Entscheidungsknoten:</li>\n<li><code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li><code>Event memory entry exists?</code></li>\n<li>Zusammenführungsknoten vor <code>try to allocate an event memory entry</code></li>\n<li>Aktionen:</li>\n<li><code>Process healing</code> mit Schleifenübergang</li>\n<li><code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li><code>try to allocate an event memory entry</code> (mit Notiz: <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>)</li>\n<li><code>Process aging</code> mit Schleifenübergang</li>\n<li><code>Delete event memory entry, CDTC=0</code></li>\n<li>Endknoten</li>\n<li>Status-, Zähler- und Schwellwertparameter: PDTC, CDTC, OCY, TFTOC, TNCTOC, HealingCounter, DemIndicatorHealingCycleCounterThreshold, DemAgingCycleCounterThreshold</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Ablauf beginnt am Startknoten unter der Vorbedingung <code>PDTC == 1</code> mit Statusübergang <code>PDTC 1-&gt;0</code> bei <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code>.</li>\n<li>Entscheidungsknoten <code>WarningIndicatorOn-CriteriaFulfilled?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ergibt die Prüfung <code>[TRUE]</code>, geht der Kontrollfluss zu <code>Process healing</code>. Bei <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0]</code> wird der Heilungszähler inkrementiert (<code>count further HealingCounter</code>). Tritt <code>[TFTOC==1]</code> ein, wird zum Endknoten verzweigt. Sobald <code>[DemIndicatorHealingCycleCounterThreshold reached]</code> erfüllt ist, wird <code>WarningIndicatorOff-CriteriaFulfilled!</code> ausgeführt.</li>\n<li>Ergibt die Prüfung <code>[FALSE]</code>, führt der Pfad am Heilungszweig vorbei zum Zusammenführungsknoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach dem Merge-Knoten folgt <code>Event memory entry exists?</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[TFTOC==1]</code> bricht der Ablauf zum Endknoten ab.</li>\n<li>Ergibt die Auswertung <code>[FALSE]</code>, wird <code>try to allocate an event memory entry</code> aufgerufen und zum Merge-Knoten zurückgeführt.</li>\n<li>Ergibt die Prüfung <code>[TRUE]</code>, wird <code>Process aging</code> erreicht.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>In <code>Process aging</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[Aging cycle completed &amp;&amp; TNCTOC==0]</code> wird <code>count further AgingCounter</code> ausgeführt.</li>\n<li>Bei <code>[TFTOC==1]</code> erfolgt der Abbruch zum Endknoten.</li>\n<li>Bei <code>[DemAgingCycleCounterThreshold reached]</code> wird <code>Delete event memory entry, CDTC=0</code> ausgeführt und die Aktivität endet am Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Zählerlogik für den Heilungsprozess: Die Heilschwelle wird nun über das Erreichen des Schwellwerts <code>DemIndicatorHealingCycleCounterThreshold</code> mittels Hochzählens (<code>count further HealingCounter</code>) gesteuert, analog zur Funktionsweise des Aging-Zählers (<code>DemAgingCycleCounterThreshold</code>). Entwickler müssen sicherstellen, dass die Konfigurationsparameter für beide Zyklusschwellen konsistent parametriert sind.</p>"}], "trans": [{"from": "FIG-d77cf47aeb8053a6", "to": "FIG-a516e16965123a8f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Startbedingung als Kommentar-Notiz ergänzt: <code>PreCondition: PDTC == 1 [OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] =&gt; PDTC 1-&gt;0</code></li>\n<li>Erste Verzweigung umbenannt: <code>Check WarningIndicator Request bit = 1</code> zu <code>WarningIndicatorOn-CriteriaFulfilled?</code></li>\n<li>Zweig <code>[FALSE]</code> der ersten Verzweigung führt nun nicht mehr direkt vor <code>Event memory entry exists</code>, sondern wird vor der Verzweigung über einen Merge-Knoten zusammengeführt</li>\n<li>Aktion <code>Process healing</code> mit Anforderung <code>[SWS_Dem_00533]</code> annotiert</li>\n<li>Zählerschleife an <code>Process healing</code> ergänzt mit Guard/Aktion: <code>[OCY completed &amp;&amp; TFTOC==0 &amp;&amp; TNCTOC==0] HealingCounter--</code></li>\n<li>Abbruchkante an <code>Process healing</code> bei Fehler ergänzt: <code>[TFTOC==1]</code> führt direkt zum Endknoten</li>\n<li>Nachfolgende Verzweigung/Aktion ersetzt: <code>Check Warning-IndicatorOffCondition</code> und Aktion <code>WarningIndicator Request bit = 0</code> ersetzt durch Übergangsbedingung <code>[HealingCounter==0]</code> auf Aktion <code>WarningIndicatorOff-CriteriaFulfilled!</code></li>\n<li>Verzweigung <code>Event memory entry exists</code> (neu <code>Event memory entry exists?</code>): Kante <code>[FALSE]</code> führt nicht mehr direkt zum Endknoten, sondern über Aktion <code>try to allocate an event memory entry</code> (mit Notiz <code>Limitation (based on Dem requirements SWS_Dem_00823 &amp; SWS_Dem_00019)</code>) zurück vor den Merge-Knoten</li>\n<li>Abbruchkante <code>[TFTOC==1]</code> an <code>Event memory entry exists?</code> ergänzt, die direkt zum Endknoten führt</li>\n<li>Zählerschleife an <code>Process aging</code> ergänzt mit Guard/Aktion: <code>[Aging cycle completed &amp;&amp; TNCTOC==0] count further AgingCounter</code></li>\n<li>Abbruchkante <code>[TFTOC==1]</code> an <code>Process aging</code> ergänzt, die direkt zum Endknoten führt</li>\n<li>Verzweigung <code>Aging completed</code> ersetzt durch Bedingungskante <code>[DemAgingCycleCounterThreshold reached]</code></li>\n<li>Aktionen <code>Delete event memory entry</code> und <code>ConfirmedDTC bit = 0</code> zusammengeführt zu einer Aktion <code>Delete event memory entry, CDTC=0</code></li>\n<li>Initialer Trigger <code>[event qualified as PASSED]</code> entfernt</li>\n</ul>"}, {"from": "FIG-a516e16965123a8f", "to": "FIG-5e55ddc4615bd15f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Aktion <code>Process healing [SWS_Dem_00533]</code>: Anforderungsbezeichner entfernt, lautet nun <code>Process healing</code></li>\n</ul>"}, {"from": "FIG-5e55ddc4615bd15f", "to": "FIG-f30cc05dfda84a1b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f30cc05dfda84a1b", "to": "FIG-8c9f388e0795110b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8c9f388e0795110b", "to": "FIG-174cf92ad4795b42", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Selbstschleife an Aktion <code>Process healing</code>: Zähleraktion von <code>HealingCounter--</code> geändert zu <code>count further HealingCounter</code></li>\n<li>Ausgehende Kante von Aktion <code>Process healing</code>: Bedingung von <code>[HealingCounter==0]</code> geändert zu <code>[DemIndicatorHealingCycleCounterThreshold reached]</code></li>\n</ul>"}, {"from": "FIG-174cf92ad4795b42", "to": "FIG-4b1967973b70d0a1", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
